// Package hypothesisranker provides scoring and ranking of investigation
// hypotheses. Hypotheses are ranked by descending Support score; ties are
// broken deterministically by lexicographic ID order so results are stable
// across repeated calls.
//
// CUE contracts live in schema.cue; this file is the Go counterpart and must
// stay in sync with that schema.
//
// Concurrency contract: all exported types are plain value types with no
// mutable state; Rank is a pure function safe to call concurrently from
// multiple goroutines.
package hypothesisranker

import (
	"math"
	"time"
)

// HypothesisStatus represents the lifecycle state of a hypothesis.
//
// CUE mirror: #HypothesisStatus in schema.cue.
type HypothesisStatus string

const (
	// StatusOpen indicates the hypothesis is under active investigation.
	StatusOpen HypothesisStatus = "open"
	// StatusSupported indicates supporting evidence has been accumulated.
	StatusSupported HypothesisStatus = "supported"
	// StatusFalsified indicates the hypothesis has been refuted by evidence.
	StatusFalsified HypothesisStatus = "falsified"
	// StatusClosed indicates the hypothesis is no longer under investigation.
	StatusClosed HypothesisStatus = "closed"
)

// GradeTierLabel is the epistemic tier assigned to a hypothesis based on its
// supporting spans (Invariant 4: grade <= weakest tier of necessary evidence).
// It mirrors evidencegrade.Tier without introducing a cross-package import so
// that this domain primitive stays pure (Invariant 8).
//
// CUE mirror: #GradeTierLabel in schema.cue.
type GradeTierLabel string

const (
	// GradeTierDirect: first-hand, unmediated observation. Strongest tier.
	GradeTierDirect GradeTierLabel = "direct"
	// GradeTierDocumentary: contemporaneous record (e.g. log entry, contract).
	GradeTierDocumentary GradeTierLabel = "documentary"
	// GradeTierCircumstantial: requires an inference step to connect to the claim.
	GradeTierCircumstantial GradeTierLabel = "circumstantial"
	// GradeTierTestimonial: statement by a human witness.
	GradeTierTestimonial GradeTierLabel = "testimonial"
	// GradeTierInferred: AI-derived or probabilistic — cannot lift a claim above this tier alone.
	GradeTierInferred GradeTierLabel = "inferred"
	// GradeTierUnset is the zero value, meaning no grade has been assigned yet.
	GradeTierUnset GradeTierLabel = ""
)

// AuthorKind identifies whether a hypothesis was produced by a human or an AI model.
//
// CUE mirror: #AuthorKind in schema.cue.
type AuthorKind string

const (
	// AuthorKindHuman indicates the hypothesis was authored by a human analyst.
	AuthorKindHuman AuthorKind = "human"
	// AuthorKindAI indicates the hypothesis was generated by an AI model.
	// When AuthorKindAI is set, Model and PromptHash should be populated.
	AuthorKindAI AuthorKind = "ai"
)

// HypothesisAuthor carries AI provenance metadata for a hypothesis (Invariant 3:
// AI contributions must be labelled; Invariant 1: provenance mandatory).
//
// CUE mirror: #HypothesisAuthor in schema.cue.
type HypothesisAuthor struct {
	// Kind is "human" or "ai".
	Kind AuthorKind

	// Model is the AI model identifier (e.g. "claude-opus-4"). Empty for human authors.
	Model string

	// PromptHash is a content-addressed hash of the prompt that produced this
	// hypothesis. Empty for human authors. Used for audit reproducibility.
	PromptHash string

	// InputDigest is a content hash of the evidence inputs fed to the model.
	// Empty for human authors.
	InputDigest string
}

// Hypothesis represents a single candidate explanation under investigation.
//
// # Additive enrichment (audit 2026-06-08)
//
// SpanRefs, Status, Author, and GradeTier were added to satisfy:
//   - Invariant 1 (provenance mandatory): SpanRefs links the ranked output to
//     the evidence spans that produced the Support score, enabling click-through
//     traceability in any UI that renders investigation results.
//   - Invariant 4 (grade <= weakest tier): GradeTier records the effective
//     epistemic tier derived from the supporting spans so callers can enforce
//     tier bounds and the UI can label AI-inferred hypotheses accordingly.
//   - Invariant 3 (AI labelled): Author records who or what produced the
//     hypothesis so AI-generated hypotheses are unambiguously tagged.
//
// All new fields are optional (zero-value safe) so existing callers that
// construct Hypothesis{ID: "...", Statement: "...", Support: x} continue to
// compile and behave identically.
//
// CUE mirror: #Hypothesis in schema.cue.
type Hypothesis struct {
	// ID uniquely identifies this hypothesis. Must be non-empty.
	ID string

	// Statement is a human-readable description of the hypothesis
	// (e.g. "Ownership gap in payments service causes incident escalation").
	Statement string

	// Support is the evidence-weighted probability score in the closed
	// interval [0, 1]. Higher values indicate stronger evidential backing.
	// 0 = no support, 1 = fully supported.
	// NaN is rejected by Validate() and treated as lowest by Rank().
	Support float64

	// SpanRefs is an ordered list of evidence span IDs whose grades contributed
	// to the Support score (Invariant 6: outputs must be traceable). Empty means
	// the hypothesis has not yet been linked to concrete evidence spans — callers
	// should treat such hypotheses as drafts rather than citable conclusions.
	SpanRefs []string

	// Status is the lifecycle state of this hypothesis (open|supported|falsified|closed).
	// The zero value is treated as StatusOpen.
	Status HypothesisStatus

	// GradeTier is the effective epistemic tier derived from the supporting spans
	// (Invariant 4: a claim's grade <= weakest tier of its necessary evidence).
	// GradeTierUnset ("") means no tier has been assigned.
	GradeTier GradeTierLabel

	// Author carries provenance information about who or what produced this
	// hypothesis. Nil means the author is unknown or unrecorded.
	Author *HypothesisAuthor

	// CreatedAt is the wall-clock time at which this hypothesis was created.
	// Zero value is valid (means the timestamp was not recorded). Added
	// 2026-06-08 as an additive audit-trail field; existing constructors that
	// omit it continue to compile and behave identically.
	//
	// CUE mirror: CreatedAt in #Hypothesis (schema.cue).
	CreatedAt time.Time
}

// Rank returns a new slice containing the same hypotheses sorted by Support
// descending. Ties are broken by lexicographic ID ascending so the order is
// fully deterministic.
//
// NaN Support values are treated as lower than any real value. If two
// hypotheses both have NaN Support, they are ordered by ID ascending.
//
// The input slice is not modified. SpanRefs slices are defensively copied.
//
// Rank never returns an error; use RankE for validated ranking.
func Rank(hypotheses []Hypothesis) []Hypothesis {
	if len(hypotheses) == 0 {
		return nil
	}
	out := make([]Hypothesis, len(hypotheses))
	copy(out, hypotheses)
	// Defensive copy of SpanRefs so callers cannot mutate the returned slices
	// back into the originals.
	for i, h := range out {
		if len(h.SpanRefs) > 0 {
			refs := make([]string, len(h.SpanRefs))
			copy(refs, h.SpanRefs)
			out[i].SpanRefs = refs
		}
	}
	// Insertion sort: correct for typical small investigation sets and
	// avoids importing "sort".
	for i := 1; i < len(out); i++ {
		key := out[i]
		j := i - 1
		for j >= 0 && less(key, out[j]) {
			out[j+1] = out[j]
			j--
		}
		out[j+1] = key
	}
	return out
}

// less reports whether a should appear before b in the ranked output.
// Primary: higher Support first (NaN is treated as lowest, -∞).
// Tie-break: lexicographically smaller ID first.
//
// NaN handling: IEEE 754 comparisons involving NaN always return false, which
// would make the comparator non-transitive and corrupt insertion sort. We
// canonicalise NaN to a sentinel of -∞ before comparing so the ordering is
// always well-defined and stable.
func less(a, b Hypothesis) bool {
	as := supportValue(a.Support)
	bs := supportValue(b.Support)
	if as != bs {
		return as > bs
	}
	return a.ID < b.ID
}

// supportValue maps a Support float to a canonical float for comparison.
// NaN is mapped to negative infinity so it always sorts last.
func supportValue(s float64) float64 {
	if math.IsNaN(s) {
		return math.Inf(-1)
	}
	return s
}
